import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  Img,
  staticFile,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
} from "../motion";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 10;
const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_BODY = "Inter, sans-serif";

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

/* ============================================================
   SCENE 1 — HERO TITLE
   ============================================================ */
const SCENE1_DURATION = 70;

const HeroScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const titleIn = springIn(frame, vfps, 8, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 22, "LIQUID");
  const subIn = springIn(frame, vfps, 30, "GENTLE");
  const ruleIn = springIn(frame, vfps, 38, "LIQUID");

  const driftY = ambientDrift(frame, 2.5, 90, "hero-title");
  const eyebrowDrift = ambientDrift(frame, 1.2, 70, "hero-eyebrow");

  const titleTx = interpolate(titleIn, [0, 1], [42, 0]);
  const titleSc = interpolate(titleIn, [0, 1], [0.94, 1]);
  const titleBlur = interpolate(titleIn, [0, 1], [8, 0]);

  return (
    <AbsoluteFill style={{ fontFamily: FONT_MARKETING }}>
      <Background />

      {/* Soft orange glow upper-right for depth */}
      <div
        style={{
          position: "absolute",
          right: "-12%",
          top: "-10%",
          width: 720,
          height: 720,
          borderRadius: "50%",
          background: `radial-gradient(closest-side, ${COLORS.orangeTint}, transparent 70%)`,
          filter: "blur(20px)",
          opacity: 0.55,
        }}
      />

      {/* Off-center anchored composition */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: `calc(28% + ${driftY}px)`,
          maxWidth: "78%",
          fontFamily: FONT_MARKETING,
        }}
      >
        {/* Eyebrow */}
        <div
          style={{
            fontFamily: FONT_BODY,
            fontWeight: 400,
            fontSize: 26,
            color: COLORS.textSubtle,
            letterSpacing: "0.22em",
            textTransform: "uppercase",
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0]) + eyebrowDrift}px)`,
            marginBottom: 28,
          }}
        >
          Product Announcement · 2025
        </div>

        {/* Headline */}
        <div
          style={{
            fontFamily: FONT_MARKETING,
            fontWeight: 600,
            fontSize: 168,
            color: COLORS.text,
            letterSpacing: "-0.035em",
            lineHeight: 0.98,
            opacity: titleIn,
            transform: `translateY(${titleTx}px) scale(${titleSc})`,
            filter: `blur(${titleBlur}px)`,
          }}
        >
          Introducing{" "}
          <span
            style={{
              display: "inline-block",
              background: COLORS.orangeTint,
              borderBottom: `4px solid ${COLORS.orange}`,
              padding: "0 18px",
              borderRadius: 10,
              color: COLORS.text,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            Actors v3
          </span>
        </div>

        {/* Thin orange rule */}
        <div
          style={{
            marginTop: 44,
            height: 3,
            width: interpolate(ruleIn, [0, 1], [0, 280]),
            background: COLORS.orange,
            borderRadius: 2,
            opacity: ruleIn,
          }}
        />

        {/* Subhead */}
        <div
          style={{
            marginTop: 26,
            fontFamily: FONT_BODY,
            fontWeight: 400,
            fontSize: 36,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.3,
            maxWidth: 760,
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [14, 0])}px)`,
          }}
        >
          The next generation of programmable scraping & automation.
        </div>
      </div>
    </AbsoluteFill>
  );
};

/* ============================================================
   SCENE 2 — THREE BENEFIT LINES
   ============================================================ */
const SCENE2_DURATION = 80;

const BENEFITS = [
  {
    label: "Faster cold starts",
    descriptor: "Boot in milliseconds, not seconds",
  },
  {
    label: "Native MCP support",
    descriptor: "Built for AI agents from day one",
  },
  {
    label: "Pay per second",
    descriptor: "You only pay for time you actually use",
  },
];

const CheckIcon: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <circle
      cx={12}
      cy={12}
      r={11}
      fill={COLORS.orangeTint}
      stroke={COLORS.orange}
      strokeWidth={1.2}
      opacity={progress}
    />
    <path
      d="M6 12.5 L10.5 17 L18 7.5"
      stroke={COLORS.orange}
      strokeWidth={2.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
      strokeDasharray={26}
      strokeDashoffset={interpolate(progress, [0, 1], [26, 0])}
    />
  </svg>
);

const BenefitsScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const headlineIn = springIn(frame, vfps, 4, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 14, "LIQUID");
  const cardIn = springIn(frame, vfps, 10, "LIQUID");

  const driftY = ambientDrift(frame, 1.8, 100, "benefits-headline");

  return (
    <AbsoluteFill style={{ fontFamily: FONT_MARKETING }}>
      <Background />

      {/* Subtle ambient glow lower-left */}
      <div
        style={{
          position: "absolute",
          left: "-8%",
          bottom: "-10%",
          width: 600,
          height: 600,
          borderRadius: "50%",
          background: `radial-gradient(closest-side, ${COLORS.orangeTint}, transparent 70%)`,
          filter: "blur(24px)",
          opacity: 0.45,
        }}
      />

      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "12%",
          right: "8%",
          fontFamily: FONT_MARKETING,
        }}
      >
        {/* Section eyebrow */}
        <div
          style={{
            fontFamily: FONT_BODY,
            fontWeight: 400,
            fontSize: 22,
            color: COLORS.textSubtle,
            letterSpacing: "0.22em",
            textTransform: "uppercase",
            opacity: headlineIn,
            marginBottom: 18,
          }}
        >
          What's new
        </div>

        {/* Headline */}
        <div
          style={{
            fontFamily: FONT_MARKETING,
            fontWeight: 600,
            fontSize: 92,
            color: COLORS.text,
            letterSpacing: "-0.028em",
            lineHeight: 1.02,
            opacity: headlineIn,
            transform: `translateY(${interpolate(headlineIn, [0, 1], [24, 0]) + driftY}px)`,
            maxWidth: "85%",
          }}
        >
          Built for{" "}
          <span
            style={{
              display: "inline-block",
              background: COLORS.orangeTint,
              borderBottom: `3px solid ${COLORS.orange}`,
              padding: "0 14px",
              borderRadius: 8,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            speed and scale
          </span>
          .
        </div>

        {/* Benefits card */}
        <div
          style={{
            marginTop: 64,
            background: "rgba(255,255,255,0.04)",
            border: `1px solid ${COLORS.border}`,
            borderRadius: 18,
            padding: "44px 52px",
            display: "flex",
            flexDirection: "column",
            gap: 32,
            maxWidth: 1280,
            opacity: cardIn,
            transform: `translateY(${interpolate(cardIn, [0, 1], [30, 0])}px)`,
            boxShadow: "0 24px 64px rgba(0,0,0,0.35)",
          }}
        >
          {BENEFITS.map((b, i) => {
            const rowIn = staggeredSpring(
              frame,
              vfps,
              i,
              28,
              TIMING.staggerItem,
              "GENTLE",
            );
            const rowDrift = ambientDrift(frame, 1, 110, `row-${i}`);
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 28,
                  opacity: rowIn,
                  transform: `translateX(${interpolate(rowIn, [0, 1], [-30, 0])}px) translateY(${rowDrift}px)`,
                }}
              >
                <CheckIcon size={56} progress={rowIn} />
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: 4,
                  }}
                >
                  <div
                    style={{
                      fontFamily: FONT_MARKETING,
                      fontWeight: 600,
                      fontSize: 52,
                      color: COLORS.text,
                      letterSpacing: "-0.015em",
                      lineHeight: 1.1,
                    }}
                  >
                    {b.label}
                  </div>
                  <div
                    style={{
                      fontFamily: FONT_BODY,
                      fontWeight: 400,
                      fontSize: 26,
                      color: COLORS.textMuted,
                      letterSpacing: "-0.003em",
                      lineHeight: 1.3,
                    }}
                  >
                    {b.descriptor}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

/* ============================================================
   SCENE 3 — SIGN-OFF
   ============================================================ */
const SCENE3_DURATION = 60;

const SignoffScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const buildIn = springIn(frame, vfps, 8, "SNAPPY");
  const runIn = springIn(frame, vfps, 16, "SNAPPY");
  const scaleIn = springIn(frame, vfps, 24, "SNAPPY");
  const ctaIn = springIn(frame, vfps, 36, "LIQUID");

  const driftY = ambientDrift(frame, 2, 95, "signoff");
  const ctaPulse = 1 + Math.sin(frame / 20) * 0.012;

  const words = [
    { text: "Build.", p: buildIn },
    { text: "Run.", p: runIn },
    { text: "Scale.", p: scaleIn },
  ];

  return (
    <AbsoluteFill style={{ fontFamily: FONT_MARKETING }}>
      <Background />

      {/* Centered radial accent */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: 1000,
          height: 1000,
          borderRadius: "50%",
          background: `radial-gradient(closest-side, ${COLORS.orangeTint}, transparent 65%)`,
          filter: "blur(28px)",
          opacity: 0.5,
          transform: "translate(-50%, -50%)",
        }}
      />

      <div
        style={{
          position: "absolute",
          left: "8%",
          right: "8%",
          top: "32%",
          fontFamily: FONT_MARKETING,
          transform: `translateY(${driftY}px)`,
        }}
      >
        {/* Eyebrow */}
        <div
          style={{
            fontFamily: FONT_BODY,
            fontWeight: 400,
            fontSize: 26,
            color: COLORS.textSubtle,
            letterSpacing: "0.22em",
            textTransform: "uppercase",
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0])}px)`,
            marginBottom: 36,
          }}
        >
          Actors v3 · Available now
        </div>

        {/* Three-word tagline */}
        <div
          style={{
            display: "flex",
            gap: 32,
            flexWrap: "wrap",
            alignItems: "baseline",
          }}
        >
          {words.map((w, i) => {
            const tx = interpolate(w.p, [0, 1], [40, 0]);
            const sc = interpolate(w.p, [0, 1], [0.92, 1]);
            const bl = interpolate(w.p, [0, 1], [6, 0]);
            const isLast = i === words.length - 1;
            return (
              <div
                key={i}
                style={{
                  fontFamily: FONT_MARKETING,
                  fontWeight: 600,
                  fontSize: 178,
                  letterSpacing: "-0.04em",
                  lineHeight: 0.95,
                  opacity: w.p,
                  transform: `translateY(${tx}px) scale(${sc})`,
                  filter: `blur(${bl}px)`,
                  color: isLast ? COLORS.text : COLORS.text,
                  position: "relative",
                }}
              >
                {isLast ? (
                  <span
                    style={{
                      display: "inline-block",
                      background: COLORS.orangeTint,
                      borderBottom: `5px solid ${COLORS.orange}`,
                      padding: "0 20px",
                      borderRadius: 12,
                    }}
                  >
                    {w.text}
                  </span>
                ) : (
                  w.text
                )}
              </div>
            );
          })}
        </div>

        {/* CTA pill */}
        <div
          style={{
            marginTop: 64,
            display: "flex",
            alignItems: "center",
            gap: 24,
            opacity: ctaIn,
            transform: `translateY(${interpolate(ctaIn, [0, 1], [20, 0])}px) scale(${ctaPulse})`,
          }}
        >
          <div
            style={{
              border: `1.5px solid ${COLORS.orange}`,
              borderRadius: 999,
              padding: "16px 36px",
              fontFamily: FONT_MARKETING,
              fontWeight: 600,
              fontSize: 30,
              color: COLORS.orange,
              letterSpacing: "-0.005em",
            }}
          >
            apify.com/actors-v3
          </div>
          <div
            style={{
              fontFamily: FONT_BODY,
              fontWeight: 400,
              fontSize: 24,
              color: COLORS.textMuted,
              letterSpacing: "0.02em",
            }}
          >
            Start building today
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

/* ============================================================
   MAIN COMPOSITION
   ============================================================ */
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE1_DURATION + TRANSITION}>
        <HeroScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE2_DURATION + TRANSITION}>
        <BenefitsScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE3_DURATION}>
        <SignoffScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export const durationInFrames =
  SCENE1_DURATION + SCENE2_DURATION + SCENE3_DURATION + TRANSITION;

export default MainComposition;
